const rows = $input.all().map((item) => item.json);
const accounts = rows.filter((row) => row.username);
const byStatus = {};
for (const account of accounts) {
  const status = String(account.accountStatus ?? 'Unknown');
  byStatus[status] = (byStatus[status] ?? 0) + 1;
}
const evidence = rows.find((row) => row._rfc)?._rfc ?? {};
return [{ json: {
  generatedAt: new Date().toISOString(),
  reviewedAccounts: accounts.length,
  accountsWithLastLogon: accounts.filter((row) => row.lastLogonAt).length,
  accountsWithoutLastLogon: accounts.filter((row) => !row.lastLogonAt).length,
  byStatus,
  evidence: {
    readOnly: evidence.readOnly === true,
    source: evidence.source ?? 'unknown',
    syntheticData: evidence.syntheticData ?? null,
    backend: evidence.backend ?? null,
    correlationId: evidence.correlationId ?? null
  }
} }];
